    }
    if(uiLogic.aicontext._entity_tag) {
        context_content = context_content+"* **任务执行目录 * 数据目录 * 资料目录**:  `{工作目录}/" + uiLogic.aicontext._entity_tag +"/" + (uiLogic.aicontext.id || (uiLogic.context.ai_knowledge_base || ''))+"`";
